-- GENERATED by `wfj generate` from data/gossip/gossip-7f.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["7f025627c56cd4c9"] = { "No! I draghi fatati non ce la fanno, {name}! Devo tornare da Jer'kai per assicurarmi che non l'abbiano trovata. Che Elune sia con te.", "." },
  ["7f040d4a9dcb17e1"] = { "La nostra scorta di equipaggiamento cresce!", "." },
  ["7f1311cecf433070"] = { "Io spacca te!", "." },
  ["7f1a8496f214abbb"] = { "Eccellente, {name}! Impari davvero in fretta.", "." },
  ["7f1e298d1842ed9a"] = { "{name}, ecco! Finalmente ho capito!", "." },
  ["7f26a1ed5bb71cfa"] = { "Sembri <sperduto/sperduta>. Posso aiutarti.", "." },
  ["7f290c980e4d02bb"] = { "Sembri un po' <sperduto/sperduta>. Chi stai cercando?", "." },
  ["7f299a4df911f3db"] = { "Vengo a ⟦Silithus=Silitus⟧ ogni anno, in questo periodo. Il clima è fenomenale per i miei calli.\n\nDovresti fare una passeggiata con me, <amico/amica>. Goderti il panorama e quant'altro.", "." },
  ["7f2aafe4276d66bd"] = { "Vedo una sofferenza senza fine. Vedo tormento. Vedo rabbia. Vedo tutto...", "." },
  ["7f33757bb19b0124"] = { "Ti servono indicazioni, <ragazzo/ragazza>?", "." },
  ["7f34fc1fc7b67411"] = { "Correte, piccoletti. Correte a dire ai vostri padroni che Eranikus è giunto a radere al suolo il loro mondo.", "." },
  ["7f38394c9e5037d2"] = { "Potrai giocare ancora domani. Adesso vieni dentro.", "." },
  ["7f3a018f572190d8"] = { "Se dovessi cadere, prendi la mia borsa. Assicurati che arrivi all'alto generale.", "." },
  ["7f405d7f45cac008"] = { "Se vogliamo fare nostre queste nuove terre, ci servono luoghi dove far riposare i nostri corpi stanchi di battaglie. Posa l'ascia accanto al fuoco e racconta le storie delle tue grandi battaglie.", "." },
  ["7f492aedf66fe8cf"] = { "Sei nel posto giusto, <ragazzo/ragazza>! La gente viene qui da tutto il mondo per imparare il mestiere del fabbro. Troverai Bengus Deepforge a martellare su un'incudine nel cuore della nostra bella città, proprio presso la ⟦Great Forge=Grande Forgia⟧.", "." },
  ["7f4d7ff2ec88234e"] = { "$962w, soldato.", "." },
  ["7f4ffba33203cd89"] = { "Un vincolo eterno mi lega a questo mondo maledetto. Che cosa desideri, mortale?", "." },
  ["7f537a0098147d27"] = { "<Benvenuto/Benvenuta> a ⟦Booty Bay=Baia del Bottino⟧, <socio/socia>. Spero che il tuo soggiorno nella mia città sia piacevole e tranquillo, soprattutto tranquillo. Abbiamo da bere in abbondanza se hai sete, e buttafuori in abbondanza se ti prudono le mani.\n\nE ora... cosa può fare per te questo umile servitore del ⟦Steamwheedle Cartel=Cartello degli Spargifumo⟧? Meglio ancora: cosa puoi fare tu per me, eh?", "." },
  ["7f587dd056e918fc"] = { "%s comincia a lanciare un incantesimo sui cuori e sulle lingue.", "." },
  ["7f5fbdbc075cb2d7"] = { "Cosa posso fare per te, {name}? Sbrigati, non ho tutto il giorno!", "." },
  ["7f6f6f60529b8ec8"] = { "La Week of the Wardens non è ancora finita... posso avere un altro Fischietto dell'Orfano?", "." },
  ["7f825e1a0ff0c3ef"] = { "Io spacca! Tu muori!", "." },
  ["7f832510cc2b39d9"] = { "Ah, visite! Devi essere in cerca d'avventure, quaggiù non vengono molti turisti. Prendi una sedia e qualcosa da bere, mettiti comod<o/a>. Di', hai l'aria di chi ha un po' di carne sulle ossa. Pensi di partecipare agli incontri nella gabbia?", "." },
  ["7f8ab926dd2433de"] = { "D'accordo, allora! Dunque, ero giù alle pozze di lava del Molten Span a collaudare la mia tuta da lava. Andava tutto a meraviglia. Riuscivo perfino a nuotare in quella roba senza un graffio!\n\nE così eccomi lì, a farmi gli affari miei, qualche bracciata a dorso, quando dal nulla questa cosa mi inghiotte in un sol boccone! Se non fosse stato per la mia tuta da lava e il distributore di pastiglie di cibo incorporato, sarebbe stata la fine!", "." },
  ["7f9397a9f5f7c9f8"] = { "Solo per un periodo limitato, rana croccante disponibile in esclusiva qui alla ⟦Darkmoon Faire=Fiera di Lunacupa⟧.", "." },
  ["7f95b3b54601b6f9"] = { "Sei gentile a cercarmi, ma le tue abilità superano le mie. Fai due chiacchiere con Sylvanna Forestmoon, proprio laggiù. Sta cercando qualcun altro da istruire.", "." },
  ["7f9a6b0aa95ca0d5"] = { "La mia ⟦Zandalar Predator's Belt=Cintura del Predatore degli Zandalari⟧ è sparita. Puoi aiutarmi, Falthir?", "." },
  ["7f9f6455b0c0e7ac"] = { "Al tuo fianco, mia signora!", "." },
  ["7fa3ff24ce9f749a"] = { "Vendo solo il miglior equipaggiamento arcano, realizzato dagli artigiani e dai maghi qui nella città di ⟦Stormwind=Roccavento⟧.", "." },
  ["7fa5108ff5305910"] = { "|cffffff00La Torre di ⟦Plaguewood=Malaselva⟧ è stata conquistata dall'⟦Horde=Orda⟧!|r", "." },
  ["7fa68a20d59c6e1e"] = { "Il pozzo rimasto puro dentro la città mi ricorda le storie che mi raccontavano da giovane, {name}. Anche nei tempi di grande dolore e sofferenza si può trovare uno spiraglio di speranza, un piccolo simbolo attorno a cui stringersi. Il popolo degli orchi vede così Thrall. È sopravvissuto contro ogni previsione e si è innalzato a guidare il nostro popolo con la sua forza e il suo esempio.\n\nNon sono sicuro che un altro orco abbia sofferto quanto lui, ma allo stesso tempo non sono sicuro che un altro orco sia forte quanto lui.", "." },
  ["7fac6b2d0492dbf5"] = { "Andrà tutto bene, bambini. Ci penserà la Luce!", "." },
  ["7faee1f13006ee9a"] = { "Direi che le probabilità di ottenere un pezzo simile siano una su un milione! Una pelle che capita una volta nella vita! Anche gli artigiani più disciplinati del mestiere fallirebbero senza dubbio diverse centinaia di volte nello scuoiare la bestia, prima di ricavarne un esemplare perfetto.", "." },
  ["7fb13120ab3e564e"] = { "Ehi, amico. Va' a parlare col mio maestro Gadrin, proprio là. Sistema quel pazzo di Zalazane per lui e io ti rimetto a posto!", "." },
  ["7fb316a9acac384f"] = { "Ho completato le armi, {name}.", "." },
  ["7fb5686183c5edfb"] = { "Rin'ji ha bisogno di aiuto!", "." },
  ["7fba6b83a9eb1701"] = { "Denti aguzzi, muscoli come cavi d'acciaio e una mente pronta come una tagliola. Questo bestione è uno dei famigli migliori che abbia mai visto. Ora, se ti interessa, potrei mostrarti un paio di cose per trasformare anche il più debole dei raptor in una forza da non sottovalutare.", "." },
  ["7fcb870696ea808e"] = { "Come va? Adoro l'odore del cuoio, tu no?", "." },
  ["7fd719988b0ba4cc"] = { "Sia noto a tutti che {name}, {class} dell'⟦Alliance=Alleanza⟧, si è <guadagnato/guadagnata> l'eterno rispetto di ⟦Ironforge=Forgiardente⟧ e dell'intera ⟦Alliance=Alleanza⟧. Ha condotto una grande opera diplomatica con il ⟦Timbermaw Hold=Rifugio dei Mordilegno⟧ e ha compiuto azioni valorose per loro a nome nostro. Ha fatto ben più di quanto il dovere richiedesse. Tre urrà per {name}, <un/una> <vero/vera> <eroe/eroina> dell'⟦Alliance=Alleanza⟧!", "." },
  ["7fd9d0ea25fbd64a"] = { "Capendo che la gemma andava protetta, ci rivolgemmo alla dea stessa.", "." },
  ["7fd9d7eee2362f37"] = { "Zayus e i suoi sacerdoti sono nella Spirit Lodge, che si trova nella ⟦Valley of Spirits=Valle degli Spiriti⟧. Cercala sul lago, in alto e a ovest della ⟦Valley of Strength=Valle della Forza⟧.", "." },
  ["7fdb586dc15ba166"] = { "Ecco! Ora va solo ricaricato...", "." },
  ["7fdc0d057b9e008d"] = { "Che c'è, Tarsis? Non so cosa fare!", "." },
  ["7fdfc75ee6e59938"] = { "Ahh... cibo. Era ora.", "." },
  ["7fe14bc086538afb"] = { "Istruttore dei Sacerdoti? Tu va' all'anello esterno del ⟦War Quarter=Quartiere della Guerra⟧ e cercali là.", "." },
  ["7fe27a35cb48f16c"] = { "Lo so, lo so: ti stai chiedendo cosa viene dopo, eh?!", "." },
  ["7fe9dec311167360"] = { "Ho perso la mia ⟦Cape of Eternal Justice=Cappa dell'Eterna Giustizia⟧. Puoi sostituirmela?", "." },
})
